style.css:
@-moz-document domain("google.com") {
body {
    background-image: url("https://i.postimg.cc/SKVQWmLM/wallpaperbetter-com-1920x1080.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
  }

  img[alt="Google"] {
    content: url("https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Supergirl_TV_series_logo.png/800px-Supergirl_TV_series_logo.png") !important;
    max-width: 350px !important;
    height: auto !important;
    object-fit: contain !important;
  }

  .L3eUgb, .o3j99 {
    background-color: transparent !important;
  }

  .RNNXgb {
    background-color: rgba(255, 255, 255, 0.3) !important;
    box-shadow: none !important;
  }
}
